const core = globalThis.Re0NarrativeCore;
if (!core) return;
const { tokenizeInlineText, READING_FONTS, READING_SIZES, fontById, normalizeReadingSettings,
  readReadingSettings, sizeById, writeReadingSettings, resolveTheme, resolveCharacter,
